import{_ as a,o as r,a as t,a2 as n}from"./chunks/framework.DCcmcJcL.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"performance/introduction.md","filePath":"performance/introduction.md","lastUpdated":1789411704000}'),o={name:"performance/introduction.md"};function i(s,e,c,l,g,h){return r(),t("div",null,e[0]||(e[0]=[n('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Bagisto is engineered for <strong>speed</strong>, <strong>scalability</strong>, and <strong>efficiency</strong>, delivering exceptional e-commerce performance even under heavy traffic loads. This comprehensive guide covers advanced performance optimization techniques, intelligent caching strategies, and scalability solutions to maximize your store&#39;s potential.</p><div class="info custom-block"><p class="custom-block-title">Performance Impact</p><p>Modern e-commerce requires <a href="https://web.dev/vitals/" target="_blank" rel="noreferrer">Core Web Vitals</a> optimization. Bagisto prioritizes excellent <a href="https://web.dev/lcp/" target="_blank" rel="noreferrer">LCP</a> (Largest Contentful Paint) and <a href="https://web.dev/cls/" target="_blank" rel="noreferrer">CLS</a> (Cumulative Layout Shift) scores for superior user experience.</p></div><h2 id="performance-architecture" tabindex="-1">Performance Architecture <a class="header-anchor" href="#performance-architecture" aria-label="Permalink to &quot;Performance Architecture&quot;">​</a></h2><h3 id="multi-layer-caching-strategy" tabindex="-1">Multi-Layer Caching Strategy <a class="header-anchor" href="#multi-layer-caching-strategy" aria-label="Permalink to &quot;Multi-Layer Caching Strategy&quot;">​</a></h3><p>Bagisto implements a sophisticated caching ecosystem designed for maximum performance:</p><table tabindex="0"><thead><tr><th><strong>Cache Layer</strong></th><th><strong>Purpose</strong></th></tr></thead><tbody><tr><td><strong>Full Page Cache (FPC)</strong></td><td>Complete storefront pages, on by default, invalidated by catalog events</td></tr><tr><td><strong>Repository cache</strong></td><td>Query results cached by the repositories, invalidated on write</td></tr><tr><td><strong>Reverse proxy cache</strong></td><td>Varnish, or the web server&#39;s own page cache, in front of PHP</td></tr><tr><td><strong>Image cache</strong></td><td>Resized images served with long-lived HTTP cache headers</td></tr><tr><td><strong>Asset Bundling</strong></td><td>Vite builds with hashed file names for permanent browser caching</td></tr></tbody></table><h3 id="high-performance-runtime" tabindex="-1">High-Performance Runtime <a class="header-anchor" href="#high-performance-runtime" aria-label="Permalink to &quot;High-Performance Runtime&quot;">​</a></h3><ul><li><strong>Laravel Octane Integration</strong>: Supercharged application performance with Swoole/RoadRunner</li><li><strong>Asynchronous Processing</strong>: Non-blocking operations for critical user interactions</li><li><strong>Memory-Resident Applications</strong>: Persistent application state for lightning-fast responses</li></ul><h3 id="enterprise-search-indexing" tabindex="-1">Enterprise Search &amp; Indexing <a class="header-anchor" href="#enterprise-search-indexing" aria-label="Permalink to &quot;Enterprise Search &amp; Indexing&quot;">​</a></h3><ul><li><strong>Elasticsearch Integration</strong>: Advanced full-text search with sub-second response times</li><li><strong>Smart Product Indexing</strong>: Optimized catalog browsing and filtering</li><li><strong>Real-time Search Suggestions</strong>: Enhanced customer discovery experience</li></ul><h2 id="performance-optimization-guides" tabindex="-1">Performance Optimization Guides <a class="header-anchor" href="#performance-optimization-guides" aria-label="Permalink to &quot;Performance Optimization Guides&quot;">​</a></h2><h3 id="core-performance-components" tabindex="-1">Core Performance Components <a class="header-anchor" href="#core-performance-components" aria-label="Permalink to &quot;Core Performance Components&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">Quick Start</p><p>The full page cache is on by default and needs nothing but a Redis store on a multi-server deployment. Start with <a href="./configure-elasticsearch.html">Elasticsearch</a> once the catalog is large enough for database search to lag, then progress through each optimization layer for maximum impact. Store media on <a href="./../advanced/file-storage.html">S3 or R2</a> before scaling to more than one web server.</p></div><h4 id="configure-elasticsearch" tabindex="-1"><strong><a href="./configure-elasticsearch.html">Configure Elasticsearch</a></strong> <a class="header-anchor" href="#configure-elasticsearch" aria-label="Permalink to &quot;**[Configure Elasticsearch](./configure-elasticsearch)**&quot;">​</a></h4><p>Advanced search engine for lightning-fast product discovery</p><ul><li><strong>Production-ready setup</strong> with real-world examples</li><li><strong>Index optimization</strong> strategies for large catalogs</li><li><strong>Performance tuning</strong> and monitoring techniques</li></ul><h4 id="configure-full-page-cache-fpc" tabindex="-1"><strong><a href="./configure-fpc.html">Configure Full Page Cache (FPC)</a></strong> <a class="header-anchor" href="#configure-full-page-cache-fpc" aria-label="Permalink to &quot;**[Configure Full Page Cache (FPC)](./configure-fpc)**&quot;">​</a></h4><p>Complete page rendering cache for maximum speed</p><ul><li><strong>Zero-configuration setup</strong> for instant performance gains</li><li><strong>Smart cache invalidation</strong> maintaining data freshness</li><li><strong>Admin panel integration</strong> with visual cache management</li></ul><h4 id="configure-varnish" tabindex="-1"><strong><a href="./configure-varnish.html">Configure Varnish</a></strong> <a class="header-anchor" href="#configure-varnish" aria-label="Permalink to &quot;**[Configure Varnish](./configure-varnish)**&quot;">​</a></h4><p>Enterprise-grade reverse proxy caching, provided by the separate <code>bagisto/bagisto-varnish</code> package</p><ul><li><strong>Custom VCL configuration</strong> for Bagisto-specific caching</li><li><strong>ESI and AJAX fragments</strong> for the parts of a page that must stay live</li></ul><h4 id="server-level-page-caches" tabindex="-1"><strong>Server-level page caches</strong> <a class="header-anchor" href="#server-level-page-caches" aria-label="Permalink to &quot;**Server-level page caches**&quot;">​</a></h4><p>Nginx FastCGI cache, LiteSpeed&#39;s LSCache and Apache&#39;s <code>mod_cache</code> are covered, with working configuration, on the <a href="./../getting-started/deployment.html">Deployment</a> page.</p><h3 id="advanced-performance-solutions" tabindex="-1">Advanced Performance Solutions <a class="header-anchor" href="#advanced-performance-solutions" aria-label="Permalink to &quot;Advanced Performance Solutions&quot;">​</a></h3><h4 id="configure-laravel-octane" tabindex="-1"><strong><a href="./configure-laravel-octane.html">Configure Laravel Octane</a></strong> <a class="header-anchor" href="#configure-laravel-octane" aria-label="Permalink to &quot;**[Configure Laravel Octane](./configure-laravel-octane)**&quot;">​</a></h4><p>High-performance application runtime with persistent memory</p><ul><li><strong>Swoole integration</strong> for production environments</li><li><strong>Development workflow</strong> optimization</li><li><strong>Performance monitoring</strong> and debugging tools</li></ul><h4 id="configure-load-balancing" tabindex="-1"><strong><a href="./configure-load-balancing.html">Configure Load Balancing</a></strong> <a class="header-anchor" href="#configure-load-balancing" aria-label="Permalink to &quot;**[Configure Load Balancing](./configure-load-balancing)**&quot;">​</a></h4><p>High-availability deployment for enterprise traffic</p><ul><li><strong>AWS Application Load Balancer</strong> configuration</li><li><strong>Multi-instance deployment</strong> strategies</li><li><strong>Database replication</strong> and failover setup</li></ul><h2 id="quick-wins" tabindex="-1">Quick Wins <a class="header-anchor" href="#quick-wins" aria-label="Permalink to &quot;Quick Wins&quot;">​</a></h2><h3 id="immediate-performance-improvements" tabindex="-1">Immediate Performance Improvements <a class="header-anchor" href="#immediate-performance-improvements" aria-label="Permalink to &quot;Immediate Performance Improvements&quot;">​</a></h3><ol><li><strong>Move the queue off <code>sync</code></strong> - product saves, imports and mail stop blocking requests</li><li><strong>Put the caches on Redis</strong> - <code>CACHE_STORE</code>, <code>SESSION_DRIVER</code> and <code>RESPONSE_CACHE_DRIVER</code></li><li><strong>Configure Elasticsearch</strong> - Enhanced search performance for larger catalogs</li><li><strong>Set up Laravel Octane</strong> - Persistent workers for the application</li></ol><h3 id="progressive-enhancement" tabindex="-1">Progressive Enhancement <a class="header-anchor" href="#progressive-enhancement" aria-label="Permalink to &quot;Progressive Enhancement&quot;">​</a></h3><ol><li><strong>Configure Load Balancing</strong> - High-availability and traffic distribution</li><li><strong>Deploy Varnish or a server-level page cache</strong> - HTTP acceleration in front of PHP</li><li><strong>Serve media from object storage</strong> - S3 or R2 behind a CDN</li><li><strong>Optimize Database Queries</strong> - Advanced indexing and query tuning</li></ol><div class="warning custom-block"><p class="custom-block-title">Production Deployment</p><p>Always test performance optimizations in staging environments before production deployment. Monitor key metrics during rollout to ensure optimal results.</p></div><p>By implementing these performance optimizations systematically, you&#39;ll transform your Bagisto store into a <strong>high-performance e-commerce powerhouse</strong> capable of handling enterprise-level traffic while delivering exceptional user experiences.</p>',39)]))}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
